<script>
  import { onMount } from 'svelte'
  import Icon from '../Icon/Icon.svelte'
  import Crumb from './Crumb.svelte'

  let {
    pathname = $bindable(''),
    class: klass = '',
    ulClass = '',
    labelCase = 'title',
    divider = 'tabler:chevron-right',
    dividerClass = '',
    ariaCurrentType = 'page',
    startingDepth = 0,

    // Slots
    children,
    before,
    after,
  } = $props()

  let trailingSlash = $derived(hasTrailingSlash(pathname))
  let crumbs = $derived(
    constructCrumbs(getURLArray(pathname), { trailingSlash }).slice(
      startingDepth,
    ),
  )

  onMount(_ => {
    if (typeof window === 'undefined') return
    if (!pathname) pathname = window.location.pathname
  })

  // Supporting functions
  function hasTrailingSlash(pathname) {
    return pathname.endsWith('/')
  }

  function getURLArray(pathname) {
    return pathname.split('/').filter(str => str)
  }

  function constructCrumbs(urlArray, { trailingSlash = true } = {}) {
    return urlArray.map((crumb, index) => {
      return {
        label: crumb,
        labelCase,
        divider: crumb.divider || divider,
        dividerClass: crumb.dividerClass || dividerClass,
        href:
          '/' +
          urlArray.slice(0, index + 1).join('/') +
          (trailingSlash ? '/' : ''),
        isLast: index === urlArray.length - 1,
        ariaCurrentType,
      }
    })
  }
</script>

<nav class={`breadcrumbs ${klass}`} aria-label="Breadcrumbs">
  <ul class={ulClass}>
    {#if before}
      <li class="crumb">
        {@render before?.()}
        <span class="crumb-divider">
          <Icon class={dividerClass} icon={divider} />
        </span>
      </li>
    {/if}

    {#if children}
      {@render children()}
    {:else}
      {#each crumbs as crumb (crumb.href)}
        <Crumb {...crumb} />
      {/each}
    {/if}
    {@render after?.()}
  </ul>
</nav>
